-- Append-only log of every listen. Run this before deploying the server that writes to it.
-- Safe to run more than once.

BEGIN;

CREATE TABLE IF NOT EXISTS play_events (
  id           BIGSERIAL PRIMARY KEY,
  -- Generated by the client, so a resent batch can't be counted twice.
  "eventId"    UUID NOT NULL UNIQUE,
  "userId"     INTEGER NOT NULL REFERENCES users (userid) ON DELETE CASCADE,
  "songRefId"  INTEGER NOT NULL REFERENCES songs (id) ON UPDATE CASCADE ON DELETE CASCADE,
  "sessionId"  UUID NOT NULL,
  source       VARCHAR(20) NOT NULL
               CHECK (source IN ('direct', 'queue', 'recommendation', 'resume')),
  -- Set only when a recommendation was played: what it was recommended for and where it ranked.
  "seedSongId" VARCHAR(255),
  position     INTEGER,
  "startedAt"  TIMESTAMPTZ NOT NULL,
  -- Time actually listened; seeking doesn't add to it.
  "playedMs"   INTEGER NOT NULL CHECK ("playedMs" >= 0),
  "durationMs" INTEGER,
  "endReason"  VARCHAR(20) NOT NULL
               CHECK ("endReason" IN ('completed', 'next', 'previous', 'selected', 'closed', 'error')),
  platform     VARCHAR(10) NOT NULL CHECK (platform IN ('app', 'web')),
  "createdAt"  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_play_events_user_started
  ON play_events ("userId", "startedAt" DESC);
CREATE INDEX IF NOT EXISTS idx_play_events_session_started
  ON play_events ("sessionId", "startedAt");
CREATE INDEX IF NOT EXISTS idx_play_events_song
  ON play_events ("songRefId");

COMMIT;
